#!/usr/bin/env python3
"""Write llms-full.txt: the full language card followed by docs/how-to.md (ADR 1110).

`tools/gen-llms-full.py` rewrites the file; `--check` fails when it is stale (the docs gate runs it).
"""
import pathlib, sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
HEAD = ("# AIL, in one file\n\n"
        "The full language card, then the how-tos (`ail ask how WORDS` finds one). Generated by "
        "`tools/gen-llms-full.py` from `docs/language-card.md` and `docs/how-to.md`; edit those.\n\n")


def build():
    card = (ROOT / "docs/language-card.md").read_text(encoding="utf-8").rstrip() + "\n"
    how = (ROOT / "docs/how-to.md").read_text(encoding="utf-8").rstrip() + "\n"
    return HEAD + card + "\n---\n\n" + how


out = ROOT / "llms-full.txt"
text = build()
if "--check" in sys.argv:
    if not out.exists() or out.read_text(encoding="utf-8") != text:
        print("llms-full.txt is stale; run tools/gen-llms-full.py")
        sys.exit(1)
    print("llms-full.txt is current")
else:
    out.write_text(text, encoding="utf-8")
    print(f"wrote {out.name} ({len(text)} bytes)")
